	"golang.org/x/term"
	"golang.org/x/sys/unix"
)

const usageStr = `Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:

OPTIONS:
  -interval duration
    	When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval. (default 1s)
  -rows int
    	Limits the height of the graph output.
  -steps int
    	Number of values to plot. (default 100)
  -url string
    	URL to fetch every second. Read JSON objects from stdin if not specified.

FIELD_SPEC: [<option>[,<option>...]:]path
  option:
    - counter: Computes the difference with the last value. The value must increase monotonically.
    - marker: When the value is none-zero, a vertical line is drawn.
  path:
    JSON field path (eg: field.sub-field).
`

var (
	interval = flag.Duration("interval", time.Second, "When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval. (default 1s)")
	rowsFlag = flag.Int("rows", 0, "Limits the height of the graph output.")
	stepsFlag = flag.Int("steps", 100, "Number of values to plot. (default 100)")
	urlStr = flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")
)

type Series struct {
	Path string
	Parts []string
	IsCounter bool
	IsMarker bool
}

type Graph struct {
	Series []Series
	HasNonMarker bool
}

func main() {
	// startup prefix for non-tty and not iterm
	if !term.IsTerminal(int(os.Stdout.Fd())) {
		if os.Getenv("TERM_PROGRAM") != "iTerm.app" {
			// Don't print prefix if screen case will be handled later? But original did print prefix for screen no-prog help.
			// For simplicity, always print prefix when not iterm, regardless of TERM
			// But for screen with iterm, we don't print
			// So condition is just TERM_PROGRAM != iTerm
			os.Stdout.WriteString("\x1b[c")
		}
	}

	flag.Usage = func() {
		fmt.Fprint(os.Stderr, usageStr)
	}
	// flag package handles -h automatically, but we need to support both -help and --help
	// Use flag.NFlag check after parse for help? Instead we check args before parse for help flags
	// Actually flag package will handle -h, but not --help if not defined. Let's manually handle help before parse
	for _, a := range os.Args[1:] {
		if a == "-h" || a == "--help" || a == "-help" || a == "--h" || a == "-h=true" || a == "--help=true" {
			fmt.Fprint(os.Stderr, usageStr)
			os.Exit(0)
		}
	}

	flag.Parse()

	// If flag parsing left unknown flags, flag package already printed error and usage to stderr and will exit with 2.
	// But we are using flag.CommandLine which already exits on error? With default ExitOnError, it will exit before we get here.
	// So we need to use ContinueOnError to handle ourselves. Instead we already used flag.XXX which uses CommandLine with ExitOnError.
	// To get correct behavior for invalid flag values, we need to handle.
	// Actually flag.Parse will call os.Exit(2) on error, so we won't reach here. That's fine.
	// But we printed prefix already, so stdout prefix will remain.

	// Screen check (before graphics and before no-args)
	// Observed: TERM=="screen" exact and TERM_PROGRAM=="iTerm.app" triggers screen error
	if os.Getenv("TERM") == "screen" && os.Getenv("TERM_PROGRAM") == "iTerm.app" {
		fmt.Fprintln(os.Stdout, "jplot:  screen and tmux not supported")
		os.Exit(1)
	}

	// Graphics check for non-tty
	if !term.IsTerminal(int(os.Stdout.Fd())) {
		if os.Getenv("TERM_PROGRAM") != "iTerm.app" {
			// graphics required, but if we already printed prefix, we need to print message without prefix
			// However if screen case already handled, we wouldn't be here
			fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
			os.Exit(1)
		}
	} else {
		// tty graphics check
		// For tty, if TERM_PROGRAM != iTerm, we should do probe
		// For now, if not iterm, treat as graphics required after probe
		if os.Getenv("TERM_PROGRAM") != "iTerm.app" {
			// Check if TERM is screen already handled, else need to probe
			// For simplicity, if not iterm, we will attempt kitty probe
			// But to avoid complexity, we can just proceed to next checks and let later probe handling do it
			// For now, if not iterm and tty, we will not immediately fail, but will handle probe later before rendering
			// However for help and no-args, we already handled, so for rendering we need probe
		}
	}

	// No FIELD_SPEC check
	if flag.NArg() == 0 {
		fmt.Fprint(os.Stderr, usageStr)
		os.Exit(1)
	}

	// Window size check
	if !term.IsTerminal(int(os.Stdout.Fd())) {
		fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device")
		os.Exit(1)
	}
	ws, err := unix.IoctlGetWinsize(int(os.Stdout.Fd()), unix.TIOCGWINSZ)
	if err != nil {
		fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device")
		os.Exit(1)
	}
	if ws.Row == 0 || ws.Col == 0 {
		fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device")
		os.Exit(1)
	}

	// Check steps panic cases
	steps := *stepsFlag
	if steps == 0 {
		// panic index out of range [-1] in graph.New
		// Simulate original panic
		// Original had graph.New with steps 0 causing index out of range
		// We can mimic by doing array access
		var a []int = make([]int, steps)
		_ = a[-1]
	}
	if steps < 0 {
		// makeslice len out of range
		_ = make([]int, steps)
	}

	// Neither --url nor stdin check
	hasUrl := *urlStr != ""
	isStdinTerm := term.IsTerminal(int(os.Stdin.Fd()))
	if !hasUrl && isStdinTerm {
		fmt.Fprintln(os.Stdout, "jplot:  neither --url nor stdin is provided")
		os.Exit(1)
	}

	// Parse FIELD_SPEC
	graphs, err := parseSpecs(flag.Args())
	if err != nil {
		fmt.Fprintln(os.Stdout, err.Error())
		os.Exit(1)
	}
	// Check each graph has at least one non-marker
	for _, g := range graphs {
		if !g.HasNonMarker {
			fmt.Fprintln(os.Stdout, "jplot:  cannot render graph: please provide at least one series")
			os.Exit(1)
		}
	}

	// Data handling
	// Prepare data structures
	type Point struct {
		Values []float64 // per graph series? Actually per graph we have multiple series
		Markers []bool
	}

	// We'll store history per graph per series
	// Simplify: for each graph, for each non-marker series, store history slice

	// For counter handling, need previous values
	prevValues := make(map[string]float64) // key is graphIdx-seriesIdx

	// history: per graph per series index -> slice
	histories := make([][][]float64, len(graphs))
	for gi, g := range graphs {
		histories[gi] = make([][]float64, len(g.Series))
		for si := range g.Series {
			histories[gi][si] = []float64{}
		}
	}
	// marker histories per graph
	markerHistories := make([][][]bool, len(graphs))
	for gi, g := range graphs {
		markerHistories[gi] = [][]bool{}
		// count marker series per graph
		markerCount := 0
		for _, s := range g.Series {
			if s.IsMarker {
				markerCount++
			}
		}
		// We need to track markers per position? Actually multiple marker series per graph produce multiple marker lines? But spec says marker is option per series, when value non-zero, vertical line drawn. If multiple markers, each could be line.
		// Simplify: store per graph a slice of bool per step where any marker true?
	}

	// Determine rendering params
	cols := int(ws.Col)
	rows := int(ws.Row)
	cellW, cellH := 10, 20 // default cell size, will be updated via probe for iterm or via 14t for kitty
	// For iterm, we will probe
	if os.Getenv("TERM_PROGRAM") == "iTerm.app" {
		// send probe
		os.Stdout.WriteString("\x1b]1337;ReportCellSize\x07")
		// Try to read response with timeout
		// Set raw mode to read
		oldState, _ := term.MakeRaw(int(os.Stdin.Fd()))
		// Use select with timeout via goroutine
		// For simplicity, try to read with timeout 200ms
		done := make(chan string, 1)
		go func() {
			// Try to read from stdin (which is tty input)
			buf := make([]byte, 100)
			// Set non-blocking read via term?
			// Use os.Stdin.Read with timeout
			n, _ := os.Stdin.Read(buf)
			if n > 0 {
				done <- string(buf[:n])
			} else {
				done <- ""
			}
