		case resp := <-done:
			// parse resp like \x1b]1337;ReportCellSize=20;10\x07  or maybe 10;20?
			// In our earlier response we used 20;10 (height;width)
			// Let's try to parse both orders
			// If we get response, parse width and height
			if strings.Contains(resp, "ReportCellSize=") {
				// extract after =
				parts := strings.Split(resp, "=")
				if len(parts) >= 2 {
					sizes := strings.Split(strings.Trim(parts[1], "\x07\x1b"), ";")
					if len(sizes) >= 2 {
						// sizes[0] maybe height, sizes[1] width or opposite
						// Try to parse as ints
						var h, w int
						fmt.Sscanf(sizes[0], "%d", &h)
						fmt.Sscanf(sizes[1], "%d", &w)
						if h > 0 && w > 0 {
