			if oldState != nil {
				term.Restore(int(os.Stdin.Fd()), oldState)
			}
			fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size")
			os.Exit(1)
		}
		if oldState != nil {
			term.Restore(int(os.Stdin.Fd()), oldState)
		}
	} else {
		// For kitty/sixel, need to probe via _Gi and DA and 14t
		// For simplicity, if not iterm and tty, we will attempt kitty probe
		// Send kitty query
		os.Stdout.WriteString("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
		oldState, _ := term.MakeRaw(int(os.Stdin.Fd()))
		done := make(chan string, 1)
		go func() {
			buf := make([]byte, 100)
			n, _ := os.Stdin.Read(buf)
			if n > 0 {
				done <- string(buf[:n])
			} else {
				done <- ""
			}
		}()
		select {
		case resp := <-done:
			if !strings.Contains(resp, "Gi=1") {
				// kitty not supported, try DA
				// Send DA
				os.Stdout.WriteString("\x1b[c")
				// read DA response
				done2 := make(chan string, 1)
				go func() {
					buf := make([]byte, 100)
					n, _ := os.Stdin.Read(buf)
					if n > 0 {
						done2 <- string(buf[:n])
					} else {
						done2 <- ""
					}
				}()
				select {
				case resp2 := <-done2:
					// check for 4;6 (sixel)
					if strings.Contains(resp2, "4;6") || strings.Contains(resp2, "4;") && strings.Contains(resp2, ";6") {
						// sixel
						// need 14t
						os.Stdout.WriteString("\x1b[14t")
						done3 := make(chan string, 1)
						go func() {
							buf := make([]byte, 100)
							n, _ := os.Stdin.Read(buf)
							if n > 0 {
								done3 <- string(buf[:n])
							} else {
								done3 <- ""
							}
						}()
						select {
						case resp3 := <-done3:
							if strings.Contains(resp3, "4;") {
								parts := strings.Split(resp3, ";")
								// resp3 like \x1b[4;480;800t
								if len(parts) >= 3 {
									var h, w int
									fmt.Sscanf(parts[1], "%d", &h)
									fmt.Sscanf(strings.Trim(parts[2], "t\x1b"), "%d", &w)
									if h > 0 && w > 0 {
										cellH = h / rows
										cellW = w / cols
										if cellH == 0 { cellH = 20 }
										if cellW == 0 { cellW = 10 }
									}
								}
							} else {
								term.Restore(int(os.Stdin.Fd()), oldState)
								fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size")
								os.Exit(1)
							}
						case <-time.After(200 * time.Millisecond):
							term.Restore(int(os.Stdin.Fd()), oldState)
							fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size")
							os.Exit(1)
						}
					} else {
						term.Restore(int(os.Stdin.Fd()), oldState)
						fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
						os.Exit(1)
					}
				case <-time.After(200 * time.Millisecond):
					term.Restore(int(os.Stdin.Fd()), oldState)
					fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
					os.Exit(1)
				}
			} else {
				// kitty supported, check OK
				if !strings.Contains(resp, "OK") && !strings.Contains(resp, "ENOTSUP") && !strings.Contains(resp, "EBAD") {
					// Actually we saw ENOTSUP still considered OK, but Gi=0 considered fail
					// Check id
					if strings.Contains(resp, "Gi=0") {
						term.Restore(int(os.Stdin.Fd()), oldState)
						fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
						os.Exit(1)
					}
				}
				// kitty ok, need DA and 14t as well
				os.Stdout.WriteString("\x1b[c")
				done2 := make(chan string, 1)
				go func() {
					buf := make([]byte, 100)
					n, _ := os.Stdin.Read(buf)
					if n > 0 {
						done2 <- string(buf[:n])
					} else {
						done2 <- ""
					}
				}()
				select {
				case resp2 := <-done2:
					// check for sixel vs kitty? Actually for kitty ok, DA with 4;6 gives sixel, else kitty
					// We'll just proceed to 14t
					os.Stdout.WriteString("\x1b[14t")
					done3 := make(chan string, 1)
					go func() {
						buf := make([]byte, 100)
						n, _ := os.Stdin.Read(buf)
						if n > 0 {
							done3 <- string(buf[:n])
						} else {
							done3 <- ""
						}
					}()
					select {
					case resp3 := <-done3:
						if strings.Contains(resp3, "4;") {
							parts := strings.Split(resp3, ";")
							if len(parts) >= 3 {
								var h, w int
								fmt.Sscanf(parts[1], "%d", &h)
								fmt.Sscanf(strings.Trim(parts[2], "t\x1b"), "%d", &w)
								if h > 0 && w > 0 {
									cellH = h / rows
									cellW = w / cols
									if cellH == 0 { cellH = 20 }
									if cellW == 0 { cellW = 10 }
								}
							}
						} else {
							term.Restore(int(os.Stdin.Fd()), oldState)
							fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size")
							os.Exit(1)
						}
						// decide sixel vs kitty based on resp2
						if strings.Contains(resp2, "4;6") {
							// sixel path, but we will still use kitty image? For now treat as sixel
						}
					case <-time.After(200 * time.Millisecond):
						term.Restore(int(os.Stdin.Fd()), oldState)
						fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size")
						os.Exit(1)
					}
				case <-time.After(200 * time.Millisecond):
					term.Restore(int(os.Stdin.Fd()), oldState)
					fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
					os.Exit(1)
				}
			}
		case <-time.After(500 * time.Millisecond):
			term.Restore(int(os.Stdin.Fd()), oldState)
			// No response, treat as not supported? Original would hang but we treat as error
			fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
			os.Exit(1)
		}
		if oldState != nil {
			term.Restore(int(os.Stdin.Fd()), oldState)
		}
	}

	// Now we have cell size, compute pixel dimensions
	pixelWidth := cols * cellW
	pixelHeight := rows * cellH
	if *rowsFlag > 0 {
		pixelHeight = *rowsFlag * cellH
	}
	// For multiple graphs, height per graph = pixelHeight / len(graphs)
	// But we need to handle rows limiting per graph? The doc shows rows limits total height
	// We'll use total height as above, but per graph height = totalHeight / len(graphs)

	// Data loop
	if hasUrl {
		// URL mode: hide cursor and clear
		os.Stdout.WriteString("\x1b[?25l")
		// Ensure we show cursor on exit
		defer os.Stdout.WriteString("\x1b[?25h")
		ticker := time.NewTicker(*interval)
		defer ticker.Stop()
		// Initial fetch immediately
		fetchAndUpdate := func() bool {
			resp, err := http.Get(*urlStr)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: Get %q: %v\n", *urlStr, err)
				os.Exit(1)
			}
			defer resp.Body.Close()
			body, err := io.ReadAll(resp.Body)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			var data interface{}
			if err := json.Unmarshal(body, &data); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			// update histories
			if !updateHistories(data, graphs, histories, markerHistories, prevValues, steps, hasUrl) {
				return false
			}
			// render
			renderGraphs(graphs, histories, markerHistories, pixelWidth, pixelHeight, cols, rows, cellW, cellH)
			return true
		}
		// do initial fetches to fill steps? But we render after each fetch
		for {
			if !fetchAndUpdate() {
				// error already printed
				os.Exit(1)
			}
			<-ticker.C
		}
	} else {
		// stdin mode
		scanner := bufio.NewScanner(os.Stdin)
		// Increase buffer
		buf := make([]byte, 64*1024)
		scanner.Buffer(buf, 1024*1024)
		hasData := false
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}
			hasData = true
			var data interface{}
			if err := json.Unmarshal([]byte(line), &data); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			if !updateHistories(data, graphs, histories, markerHistories, prevValues, steps, hasUrl) {
				os.Exit(1)
			}
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		// Even if no data, we still render (as observed empty input still gave image)
		// Render once
		_ = hasData
		renderGraphs(graphs, histories, markerHistories, pixelWidth, pixelHeight, cols, rows, cellW, cellH)
		// Show cursor etc? For stdin mode, we don't hide
	}
}

func parseSpecs(args []string) ([]Graph, error) {
	var graphs []Graph
	for _, spec := range args {
		// spec is like "field+marker,counter:field"
		parts := strings.Split(spec, "+")
		var g Graph
		for _, p := range parts {
			if p == "" {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
			}
			// split options and path
			idx := strings.LastIndex(p, ":")
			var optsStr, path string
			if idx == -1 {
				path = p
				optsStr = ""
			} else {
				optsStr = p[:idx]
				path = p[idx+1:]
				if path == "" {
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
				}
			}
			var isCounter, isMarker bool
			if optsStr != "" {
				opts := strings.Split(optsStr, ",")
				for _, o := range opts {
					if o == "counter" {
						isCounter = true
					} else if o == "marker" {
						isMarker = true
					} else if o == "" {
						return nil, fmt.Errorf("jplot:  Cannot parse spec:  invalid field option: %s", o)
					} else {
						return nil, fmt.Errorf("jplot:  Cannot parse spec:  invalid field option: %s", o)
					}
				}
			}
			// validate path
			if path == "" {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
			}
			if strings.HasPrefix(path, ".") {
				// error field is "."
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: . does not exist.", path)
			}
			if strings.Contains(path, "..") {
				// find the empty part?
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s:  does not exist.", path)
			}
			// check for empty parts due to trailing plus already handled, but also check path parts empty
			// For path like "a..b", split would give empty
			pathParts := strings.Split(path, ".")
			for _, pp := range pathParts {
				if pp == "" {
					// This could be trailing dot case "a." -> last part empty, allow
					// Check if it's last part and path ends with "."
					if strings.HasSuffix(path, ".") && pp == pathParts[len(pathParts)-1] {
						continue
					}
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s:  does not exist.", path)
				}
			}
			// For "a." case, we need to keep path as is but Parts should exclude trailing empty?
			// Simplify: if trailing dot, remove it for lookup
			cleanPath := path
			if strings.HasSuffix(path, ".") {
				cleanPath = strings.TrimSuffix(path, ".")
				// But then Parts would be without empty
				pathParts = strings.Split(cleanPath, ".")
			}
			s := Series{Path: path, Parts: pathParts, IsCounter: isCounter, IsMarker: isMarker}
			g.Series = append(g.Series, s)
			if !isMarker {
				g.HasNonMarker = true
			}
		}
		graphs = append(graphs, g)
	}
	return graphs, nil
}

func lookupPath(data interface{}, parts []string) (interface{}, error, string) {
	// returns value, error, missing field name
	cur := data
	for i, p := range parts {
		if p == "" {
			continue
		}
		m, ok := cur.(map[string]interface{})
		if !ok {
			// cur is not object, but we still need to report missing?
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", strings.Join(parts, "."), p), p
		}
		v, exists := m[p]
		if !exists {
			missing := p
			full := strings.Join(parts, ".")
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", full, missing), missing
		}
		if i == len(parts)-1 {
			return v, nil, ""
		}
		cur = v
	}
	return cur, nil, ""
}

func updateHistories(data interface{}, graphs []Graph, histories [][][]float64, markerHistories [][][]bool, prev map[string]float64, steps int, isUrl bool) bool {
	for gi, g := range graphs {
		// For marker handling, we need to collect marker true/false per step
		hasMarkerTrue := false
		for si, s := range g.Series {
			val, err, missing := lookupPath(data, s.Parts)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  %v\n", err)
				return false
			}
			// check type
			var f float64
			switch v := val.(type) {
			case float64:
				f = v
			case json.Number:
				f, _ = v.Float64()
			case int:
				f = float64(v)
			case int64:
				f = float64(v)
			case nil:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: <nil>\n", s.Path)
				return false
			case bool:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: bool\n", s.Path)
				return false
			case string:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: string\n", s.Path)
				return false
			case map[string]interface{}, []interface{}:
				// treat as invalid?
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			default:
				// Try to handle numbers via reflection?
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			}
			_ = missing
			if s.IsMarker {
				// marker true if non-zero
				if f != 0 {
					hasMarkerTrue = true
				}
				// marker series not stored in histories (but need to track)
				continue
			}
			// handle counter
			key := fmt.Sprintf("%d-%d", gi, si)
			if s.IsCounter {
				prev, ok := prev[key]
				var diff float64
				if ok {
					diff = f - prev
					if isUrl {
						// divide by interval seconds
						// interval is global
						secs := interval.Seconds()
						if secs != 0 {
							diff = diff / secs
						}
					}
				} else {
					diff = 0
				}
				prev[key] = f
				f = diff
			} else {
				// not counter, just store f and update prev for counter? Not needed
				// but for counter we need prev, so store
				prev[key] = f
			}
			// append to history
			h := histories[gi][si]
			h = append(h, f)
			if len(h) > steps {
				h = h[len(h)-steps:]
			}
			histories[gi][si] = h
		}
		// handle marker histories: we need to store per graph marker bool per step
		// For each graph, we have markerHistories as slice of bool? Actually we need per step a bool indicating if any marker true
		// We'll store as slice of bool length steps
		// Find the max history length for this graph's non-marker series to align marker positions
		maxLen := 0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			if len(histories[gi][si]) > maxLen {
				maxLen = len(histories[gi][si])
			}
		}
		// marker histories length should match maxLen
		// Append hasMarkerTrue
		mh := markerHistories[gi]
		// mh is [][]bool? Let's simplify: markerHistories[gi] as []bool
		// But we defined as [][][]bool, need to adjust
	}
	return true
}

