				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: . does not exist.", path)
			}
			if strings.Contains(path, "..") {
				// find the empty part?
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s:  does not exist.", path)
			}
			// check for empty parts due to trailing plus already handled, but also check path parts empty
			// For path like "a..b", split would give empty
			pathParts := strings.Split(path, ".")
			for _, pp := range pathParts {
				if pp == "" {
					// This could be trailing dot case "a." -> last part empty, allow
					// Check if it's last part and path ends with "."
					if strings.HasSuffix(path, ".") && pp == pathParts[len(pathParts)-1] {
						continue
					}
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s:  does not exist.", path)
				}
			}
			// For "a." case, we need to keep path as is but Parts should exclude trailing empty?
			// Simplify: if trailing dot, remove it for lookup
			cleanPath := path
			if strings.HasSuffix(path, ".") {
				cleanPath = strings.TrimSuffix(path, ".")
				// But then Parts would be without empty
				pathParts = strings.Split(cleanPath, ".")
			}
			s := Series{Path: path, Parts: pathParts, IsCounter: isCounter, IsMarker: isMarker}
			g.Series = append(g.Series, s)
			if !isMarker {
				g.HasNonMarker = true
			}
		}
		graphs = append(graphs, g)
	}
	return graphs, nil
}

func lookupPath(data interface{}, parts []string) (interface{}, error, string) {
	// returns value, error, missing field name
	cur := data
	for i, p := range parts {
		if p == "" {
			continue
		}
		m, ok := cur.(map[string]interface{})
		if !ok {
			// cur is not object, but we still need to report missing?
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", strings.Join(parts, "."), p), p
		}
		v, exists := m[p]
		if !exists {
			missing := p
			full := strings.Join(parts, ".")
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", full, missing), missing
		}
		if i == len(parts)-1 {
			return v, nil, ""
		}
		cur = v
	}
	return cur, nil, ""
}

func updateHistories(data interface{}, graphs []Graph, histories [][][]float64, markerHistories [][][]bool, prev map[string]float64, steps int, isUrl bool) bool {
