				return false
			case string:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: string\n", s.Path)
				return false
			case map[string]interface{}, []interface{}:
				// treat as invalid?
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			default:
				// Try to handle numbers via reflection?
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			}
			_ = missing
			if s.IsMarker {
