			// use select via timeout
			ch := make(chan string, 1)
			go func() {
				buf := make([]byte, 256)
				// set non-blocking? Use read with timeout via goroutine
				n, _ := tty.Read(buf)
				if n > 0 {
					ch <- string(buf[:n])
				} else {
					ch <- ""
				}
