		} else {
			// fallback to stdin
			oldState, _ := term.MakeRaw(int(os.Stdin.Fd()))
			ch := make(chan string, 1)
			go func() {
				buf := make([]byte, 256)
				n, _ := os.Stdin.Read(buf)
				if n > 0 {
					ch <- string(buf[:n])
				} else {
					ch <- ""
				}
