		if resp == "" || !strings.Contains(resp, "ReportCellSize") {
			fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size")
			os.Exit(1)
		}
		// parse resp like \x1b]1337;ReportCellSize=20;10\x07  (height; width)
		// It could be "ReportCellSize=10;20" or "ReportCellSize=20;10"
		// Extract after =
		idx := strings.Index(resp, "ReportCellSize=")
		if idx != -1 {
			sub := resp[idx+len("ReportCellSize="):]
			// trim trailing \x07 and \x1b
			sub = strings.Trim(sub, "\x07\x1b")
			// also trim after \x07
			if strings.Contains(sub, "\x07") {
