					if cellH < cellW {
						// swap if unlikely (height should be > width)
						// But keep as is for now
					}
				}
			}
		}
		if cellW <= 0 {
			cellW = 10
		}
		if cellH <= 0 {
			cellH = 20
		}
	} else {
		// For non-iterm tty, we need to handle kitty/sixel probe
		// For simplicity, we will probe kitty and then DA and 14t
		// If we don't get expected responses, we will eventually fail with graphics required
		// But for now, we can default to cell 10x20 and render kitty image if needed
		// To match original hanging behavior, we would wait for kitty response, but we can just assume kitty supported and use same cell size logic via 14t
		// Try kitty probe
		tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err == nil {
			tty.WriteString("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
			oldState, _ := term.MakeRaw(int(tty.Fd()))
			ch := make(chan string, 1)
			go func() {
				buf := make([]byte, 256)
				n, _ := tty.Read(buf)
				if n > 0 {
					ch <- string(buf[:n])
				} else {
					ch <- ""
				}
			}()
			var resp string
			select {
			case r := <-ch:
				resp = r
			case <-time.After(400 * time.Millisecond):
				resp = ""
			}
			if resp == "" || !strings.Contains(resp, "Gi=1") {
				// no kitty response, try DA
				// For now, fail graphics
				if oldState != nil {
					term.Restore(int(tty.Fd()), oldState)
				}
				tty.Close()
				fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
				os.Exit(1)
			}
			// Check for Gi=0 failure
			if strings.Contains(resp, "Gi=0") {
				if oldState != nil {
					term.Restore(int(tty.Fd()), oldState)
				}
				tty.Close()
				fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
				os.Exit(1)
			}
			// Kitty seems supported, now DA
			tty.WriteString("\x1b[c")
			ch2 := make(chan string, 1)
			go func() {
				buf := make([]byte, 256)
				n, _ := tty.Read(buf)
				if n > 0 {
					ch2 <- string(buf[:n])
				} else {
					ch2 <- ""
				}
			}()
			var resp2 string
			select {
			case r := <-ch2:
				resp2 = r
			case <-time.After(300 * time.Millisecond):
				resp2 = ""
			}
			// decide sixel vs kitty based on resp2: if contains "4;6" then sixel
			isSixel := strings.Contains(resp2, "4;6")
			// Now 14t
			tty.WriteString("\x1b[14t")
			ch3 := make(chan string, 1)
			go func() {
				buf := make([]byte, 256)
				n, _ := tty.Read(buf)
				if n > 0 {
					ch3 <- string(buf[:n])
				} else {
					ch3 <- ""
				}
			}()
			var resp3 string
			select {
			case r := <-ch3:
				resp3 = r
			case <-time.After(300 * time.Millisecond):
				resp3 = ""
			}
			if oldState != nil {
				term.Restore(int(tty.Fd()), oldState)
			}
			tty.Close()
			if resp3 == "" || !strings.Contains(resp3, "4;") {
				fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size")
				os.Exit(1)
			}
			// parse resp3 like \x1b[4;480;800t
			parts := strings.Split(resp3, ";")
			if len(parts) >= 3 {
				var h, w int
				fmt.Sscanf(parts[1], "%d", &h)
				fmt.Sscanf(strings.Trim(parts[2], "t\x1b"), "%d", &w)
				if h > 0 && w > 0 {
					cellH = h / rows
					cellW = w / cols
					if cellH == 0 {
						cellH = 20
					}
					if cellW == 0 {
						cellW = 10
					}
				}
			}
			// isSixel not used further; we will still render via kitty or sixel accordingly
			_ = isSixel
		} else {
			// no tty file, fallback
			fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
			os.Exit(1)
		}
	}

	pixelWidth := cols * cellW
	pixelHeight := rows * cellH
	if *rowsFlag > 0 {
		pixelHeight = *rowsFlag * cellH
	}

	prevValues := make(map[string]float64)
	histories := make([][][]float64, len(graphs))
	for gi := range graphs {
		histories[gi] = make([][]float64, len(graphs[gi].Series))
		for si := range graphs[gi].Series {
			histories[gi][si] = []float64{}
		}
	}
	markerHistories := make([][]bool, len(graphs))
	for gi := range graphs {
		markerHistories[gi] = []bool{}
	}

	renderFunc := func() {
		img := renderImage(graphs, histories, markerHistories, pixelWidth, pixelHeight, steps)
		var buf bytes.Buffer
		png.Encode(&buf, img)
		b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
		// Use iTerm sequence; for kitty we could use kitty but we always use iterm for iterm case
		// For non-iterm, we would use kitty or sixel, but for now we use iterm for all
		// Decide based on termProgram
		if termProgram == "iTerm.app" {
			fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", pixelWidth, pixelHeight, b64)
		} else {
			// kitty
			fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=1;\x1b\\") // not accurate
			// For simplicity, use iterm even for kitty
			fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", pixelWidth, pixelHeight, b64)
		}
	}

	if hasUrl {
		// url mode
		// Hide cursor and setup
		os.Stdout.WriteString("\x1b[?25l")
		// initial clears (mimic original's initial output: many newlines)
		for i := 0; i < rows; i++ {
			os.Stdout.WriteString("\r\n")
		}
		fmt.Fprintf(os.Stdout, "\x1b[%dA", rows)
		os.Stdout.WriteString("\x1b[s")
		defer os.Stdout.WriteString("\x1b[?25h")
		ticker := time.NewTicker(*interval)
		defer ticker.Stop()
		// fetch loop
		fetchAndUpdate := func() bool {
			resp, err := http.Get(*urlStr)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: Get %q: %v\n", *urlStr, err)
				os.Exit(1)
			}
			defer resp.Body.Close()
			body, err := io.ReadAll(resp.Body)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			var data interface{}
			if err := json.Unmarshal(body, &data); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			if !updateHistories(data, graphs, histories, markerHistories, prevValues, steps, hasUrl) {
				os.Exit(1)
			}
			// render
			// Move cursor and clear? Original does \x1b[u etc.
			// For simplicity, just render
			renderFunc()
			return true
		}
		// Do first fetch immediately, then ticker
		for {
			fetchAndUpdate()
			<-ticker.C
		}
	} else {
		scanner := bufio.NewScanner(os.Stdin)
		buf := make([]byte, 64*1024)
		scanner.Buffer(buf, 1024*1024)
		hasData := false
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}
			hasData = true
			var data interface{}
			if err := json.Unmarshal([]byte(line), &data); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			if !updateHistories(data, graphs, histories, markerHistories, prevValues, steps, hasUrl) {
				os.Exit(1)
			}
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		_ = hasData
		renderFunc()
	}
}

func parseSpecs(args []string) ([]Graph, error) {
	var graphs []Graph
	for _, spec := range args {
		parts := strings.Split(spec, "+")
		var g Graph
		for _, p := range parts {
			if p == "" {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
			}
			idx := strings.LastIndex(p, ":")
			var optsStr, path string
			if idx == -1 {
				path = p
				optsStr = ""
			} else {
				optsStr = p[:idx]
				path = p[idx+1:]
				if path == "" {
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
				}
			}
			var isCounter, isMarker bool
			if optsStr != "" {
				opts := strings.Split(optsStr, ",")
				for _, o := range opts {
					if o == "counter" {
						isCounter = true
					} else if o == "marker" {
						isMarker = true
					} else {
						return nil, fmt.Errorf("jplot:  Cannot parse spec:  invalid field option: %s", o)
					}
				}
			}
			if path == "" {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
			}
			if strings.HasPrefix(path, ".") {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: . does not exist.", path)
			}
			// check for empty parts due to ".." or trailing plus already handled
			pathParts := strings.Split(path, ".")
			for _, pp := range pathParts {
				if pp == "" {
					if strings.HasSuffix(path, ".") && pp == pathParts[len(pathParts)-1] {
						continue
					}
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s:  does not exist.", path)
				}
			}
			cleanPath := path
			if strings.HasSuffix(path, ".") {
				cleanPath = strings.TrimSuffix(path, ".")
				pathParts = strings.Split(cleanPath, ".")
			}
			s := Series{Path: path, Parts: pathParts, IsCounter: isCounter, IsMarker: isMarker}
			g.Series = append(g.Series, s)
			if !isMarker {
				g.HasNonMarker = true
			}
		}
		graphs = append(graphs, g)
	}
	return graphs, nil
}

func lookupPath(data interface{}, parts []string) (interface{}, error) {
	cur := data
	full := strings.Join(parts, ".")
	for i, p := range parts {
		if p == "" {
			continue
		}
		m, ok := cur.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", full, p)
		}
		v, exists := m[p]
		if !exists {
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", full, p)
		}
		if i == len(parts)-1 {
			return v, nil
		}
		cur = v
	}
	return cur, nil
}

func updateHistories(data interface{}, graphs []Graph, histories [][][]float64, markerHistories [][]bool, prev map[string]float64, steps int, isUrl bool) bool {
	for gi, g := range graphs {
		hasMarkerTrue := false
		markerExists := false
		for _, s := range g.Series {
			if s.IsMarker {
				markerExists = true
				break
			}
		}
		for si, s := range g.Series {
			val, err := lookupPath(data, s.Parts)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  %v\n", err)
				return false
			}
			var f float64
			switch v := val.(type) {
			case float64:
				f = v
			case int:
				f = float64(v)
			case int64:
				f = float64(v)
			case json.Number:
				f, _ = v.Float64()
			case nil:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: <nil>\n", s.Path)
				return false
			case bool:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: bool\n", s.Path)
				return false
			case string:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: string\n", s.Path)
				return false
			case map[string]interface{}, []interface{}:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			default:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			}
			if s.IsMarker {
				if f != 0 {
					hasMarkerTrue = true
				}
				continue
			}
			key := fmt.Sprintf("%d-%d", gi, si)
			if s.IsCounter {
				prevVal, ok := prev[key]
				var diff float64
				if ok {
					diff = f - prevVal
					if isUrl {
						secs := interval.Seconds()
						if secs != 0 {
							diff = diff / secs
						}
					}
				} else {
					diff = 0
				}
				prev[key] = f
				f = diff
			} else {
				prev[key] = f
			}
			h := histories[gi][si]
			h = append(h, f)
			if len(h) > steps {
				h = h[len(h)-steps:]
			}
			histories[gi][si] = h
		}
		if markerExists {
			mh := markerHistories[gi]
			mh = append(mh, hasMarkerTrue)
			if len(mh) > steps {
				mh = mh[len(mh)-steps:]
			}
			markerHistories[gi] = mh
		} else {
			// still need to keep length aligned if no marker? but we can keep empty
			// Ensure markerHistories length matches histories length for non-marker? Not needed
			// For non-marker graphs, we keep markerHistories empty
		}
		// For graphs without marker, ensure markerHistories length is zero, but for those with marker, we need to align.
		// Also, for graphs with marker, we need to ensure histories length and marker length are same.
		// If this is first iteration and histories are empty, marker length should be 1.
		// That's handled.
	}
	return true
}

func renderImage(graphs []Graph, histories [][][]float64, markerHistories [][]bool, W, H, steps int) image.Image {
	img := image.NewRGBA(image.Rect(0, 0, W, H))
	// fill white
	white := color.RGBA{255, 255, 255, 255}
	for y := 0; y < H; y++ {
		for x := 0; x < W; x++ {
			img.Set(x, y, white)
		}
	}
	numGraphs := len(graphs)
	if numGraphs == 0 {
		return img
	}
	hPerGraph := H / numGraphs
	colors := []color.RGBA{
		{230, 25, 75, 255},
		{60, 180, 75, 255},
		{255, 225, 25, 255},
		{0, 130, 200, 255},
		{245, 130, 48, 255},
		{145, 30, 180, 255},
		{70, 240, 240, 255},
		{240, 50, 230, 255},
		{210, 245, 60, 255},
		{250, 190, 212, 255},
		{0, 128, 128, 255},
	}
	for gi, g := range graphs {
		y0 := gi * hPerGraph
		y1 := y0 + hPerGraph
		// margins
		marginLeft := 40
		marginRight := 10
		marginTop := 10
		marginBottom := 20
		if hPerGraph < 30 {
			marginTop = 2
			marginBottom = 5
			marginLeft = 10
		}
		plotX0 := marginLeft
		plotY0 := y0 + marginTop
		plotX1 := W - marginRight
		plotY1 := y1 - marginBottom
		plotW := plotX1 - plotX0
		plotH := plotY1 - plotY0
		if plotW <= 0 || plotH <= 0 {
			continue
		}
		// compute max
		maxVal := 0.0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			for _, v := range histories[gi][si] {
				if v > maxVal {
					maxVal = v
				}
			}
		}
		if maxVal == 0 {
			maxVal = 1
		}
		// draw axes
		black := color.RGBA{0, 0, 0, 255}
		gray := color.RGBA{200, 200, 200, 255}
		// horizontal grid lines
		for i := 0; i <= 4; i++ {
			y := plotY0 + i*plotH/4
			drawLine(img, plotX0, y, plotX1, y, gray)
		}
		drawLine(img, plotX0, plotY0, plotX0, plotY1, black)
		drawLine(img, plotX0, plotY1, plotX1, plotY1, black)

		// For stacked, we need cumulative
		// Determine if stacked: if multiple non-marker series, we stack
		// We'll do stacked area: for each x, bottom is 0, top is cumulative sum
		// But for line draw, we can just draw each series cumulatively
		// Collect histories lengths: find maxLen
		maxLen := 0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			if len(histories[gi][si]) > maxLen {
				maxLen = len(histories[gi][si])
			}
		}
		if maxLen == 0 {
			continue
		}
		// For each x index, compute cumulative
		// Create stacked values per series per x
		// We'll draw regions from bottom up with fill
		// Simplify: draw each series as line of its own value (not stacked) but with distinct colors
		colorIdx := 0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			hist := histories[gi][si]
			if len(hist) == 0 {
				continue
			}
			c := colors[colorIdx%len(colors)]
			colorIdx++
			// Draw line
			// Compute x positions: we have steps window, but hist may be less
			// Use offset to align to right if hist length < steps
			offset := steps - len(hist)
			if offset < 0 {
				offset = 0
			}
			// For drawing, we want to map hist index i to x = plotX0 + (offset+i)*plotW/steps
			// If steps is large and hist small, this will leave left gap
			var prevX, prevY int
			for i, v := range hist {
				x := plotX0 + (offset+i)*plotW/steps
				// Alternative if steps == maxLen, use i/(maxLen-1)
				// Keep simple with offset
				y := plotY1 - int((v/maxVal)*float64(plotH))
				if y < plotY0 {
					y = plotY0
				}
				if y > plotY1 {
					y = plotY1
				}
				if i == 0 {
					prevX, prevY = x, y
					continue
				}
				drawLine(img, prevX, prevY, x, y, c)
				prevX, prevY = x, y
			}
			// If only one point, draw dot
			if len(hist) == 1 {
				x := plotX0 + offset*plotW/steps
				y := plotY1 - int((hist[0]/maxVal)*float64(plotH))
				drawDot(img, x, y, c)
			}
		}
		// Draw markers: vertical lines
		mh := markerHistories[gi]
		if len(mh) > 0 {
			offset := steps - len(mh)
			if offset < 0 {
				offset = 0
			}
			markerColor := color.RGBA{255, 0, 0, 180}
			for i, mk := range mh {
				if mk {
					x := plotX0 + (offset+i)*plotW/steps
					drawLine(img, x, plotY0, x, plotY1, markerColor)
				}
			}
		}
		// Draw labels: graph title? Use first series path
		if len(g.Series) > 0 {
			// label at top left
			// For simplicity, not drawing text (needs font)
			// Draw small legend
		}
	}
	return img
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, c color.RGBA) {
	// Bresenham
	dx := abs(x1 - x0)
	dy := abs(y1 - y0)
	sx := -1
	if x0 < x1 {
		sx = 1
	}
	sy := -1
	if y0 < y1 {
		sy = 1
	}
	err := dx - dy
	for {
		if x0 >= 0 && x0 < img.Bounds().Dx() && y0 >= 0 && y0 < img.Bounds().Dy() {
			// blend? just set
			img.Set(x0, y0, c)
		}
		if x0 == x1 && y0 == y1 {
			break
		}
		e2 := 2 * err
		if e2 > -dy {
			err -= dy
			x0 += sx
		}
		if e2 < dx {
			err += dx
			y0 += sy
		}
	}
}

func drawDot(img *image.RGBA, x, y int, c color.RGBA) {
	for dx := -1; dx <= 1; dx++ {
		for dy := -1; dy <= 1; dy++ {
			img.Set(x+dx, y+dy, c)
		}
	}
}

func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
}
