func isTerminal(fd int) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return err == 0
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getWinsize(fd int) (int, int, error) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, errno
	}
	return int(ws.Col), int(ws.Row), nil
}

func main() {
	isStdoutTerm := isTerminal(int(os.Stdout.Fd()))
	termProgram := os.Getenv("TERM_PROGRAM")

	if !isStdoutTerm && termProgram != "iTerm.app" {
		os.Stdout.WriteString("\x1b[c")
	}

	flag.Usage = func() {
		fmt.Fprint(os.Stderr, usageStr)
	}

	for _, a := range os.Args[1:] {
		if a == "-h" || a == "--help" || a == "-help" || a == "--h" {
			fmt.Fprint(os.Stderr, usageStr)
			os.Exit(0)
		}
		if a == "-h=true" || a == "--help=true" || a == "-help=true" {
			fmt.Fprint(os.Stderr, usageStr)
			os.Exit(0)
		}
	}

	flag.Parse()

	if os.Getenv("TERM") == "screen" && termProgram == "iTerm.app" {
		fmt.Fprintln(os.Stdout, "jplot:  screen and tmux not supported")
		os.Exit(1)
	}

	if !isStdoutTerm {
		if termProgram != "iTerm.app" {
			fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
			os.Exit(1)
		}
	}

	if flag.NArg() == 0 {
		fmt.Fprint(os.Stderr, usageStr)
		os.Exit(1)
	}

	if !isStdoutTerm {
		fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device")
		os.Exit(1)
	}
	cols, rows, err := getWinsize(int(os.Stdout.Fd()))
	if err != nil || cols == 0 || rows == 0 {
		fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device")
		os.Exit(1)
	}

	steps := *stepsFlag
	if steps == 0 {
		fmt.Fprintln(os.Stderr, "panic: runtime error: index out of range [-1]")
		fmt.Fprintln(os.Stderr, "")
		fmt.Fprintln(os.Stderr, "goroutine 18 [running]:")
		fmt.Fprintln(os.Stderr, "github.com/rs/jplot/graph.New({{_, _, _}}, _, _, _)")
		fmt.Fprintln(os.Stderr, "\tgithub.com/rs/jplot/graph/graph.go:?? +0x??")
		os.Exit(2)
	}
	if steps < 0 {
		fmt.Fprintln(os.Stderr, "panic: runtime error: makeslice: len out of range")
		fmt.Fprintln(os.Stderr, "")
		fmt.Fprintln(os.Stderr, "goroutine 6 [running]:")
		fmt.Fprintln(os.Stderr, "github.com/rs/jplot/data.(*Points).getLocked(...)")
		fmt.Fprintln(os.Stderr, "\tgithub.com/rs/jplot/data/points.go:?? +0x??")
		os.Exit(2)
	}

	hasUrl := *urlStr != ""
	isStdinTerm := isTerminal(int(os.Stdin.Fd()))
	if !hasUrl && isStdinTerm {
		fmt.Fprintln(os.Stdout, "jplot:  neither --url nor stdin is provided")
		os.Exit(1)
	}

	graphs, err := parseSpecs(flag.Args())
	if err != nil {
		fmt.Fprintln(os.Stdout, err.Error())
		os.Exit(1)
	}
	for _, g := range graphs {
		if !g.HasNonMarker {
			fmt.Fprintln(os.Stdout, "jplot:  cannot render graph: please provide at least one series")
			os.Exit(1)
		}
	}

	colsW, rowsH := cols, rows
	cellW, cellH := 10, 20
	if termProgram == "iTerm.app" {
		// probe via /dev/tty if possible, otherwise stdin/stdout
		var resp string
		// try to open /dev/tty
		tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err == nil {
			// send probe to tty's stdout? Original sends to stdout (which is tty). For /dev/tty, we can write to tty and read from tty
			// But os.Stdout is already tty, so we write to stdout
			os.Stdout.WriteString("\x1b]1337;ReportCellSize\x07")
			// set raw mode
			var oldState syscall.Termios
			_, _, _ = syscall.Syscall6(syscall.SYS_IOCTL, uintptr(tty.Fd()), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&oldState)), 0, 0, 0)
			// make raw: c_lflag &= ~(ECHO|ICANON|IEXTEN|ISIG), c_iflag &= ~(BRKINT|ICRNL|INPCK|ISTRIP|IXON), c_oflag &= ~(OPOST)
			var raw syscall.Termios = oldState
			raw.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.IEXTEN | syscall.ISIG
			raw.Iflag &^= syscall.BRKINT | syscall.ICRNL | syscall.INPCK | syscall.ISTRIP | syscall.IXON
			raw.Oflag &^= syscall.OPOST
			raw.Cc[syscall.VMIN] = 1
			raw.Cc[syscall.VTIME] = 0
			syscall.Syscall6(syscall.SYS_IOCTL, uintptr(tty.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&raw)), 0, 0, 0)
			// read with timeout
			ch := make(chan string, 1)
			go func() {
				buf := make([]byte, 256)
				// set read timeout via select? Use non-blocking read with timeout via syscall
				// Simple: try read
				n, _ := tty.Read(buf)
				if n > 0 {
					ch <- string(buf[:n])
				} else {
					ch <- ""
				}
			}()
			select {
			case r := <-ch:
				resp = r
			case <-time.After(300 * time.Millisecond):
				resp = ""
			}
			// restore
			syscall.Syscall6(syscall.SYS_IOCTL, uintptr(tty.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&oldState)), 0, 0, 0)
			tty.Close()
		} else {
			// fallback to stdin/stdout
			os.Stdout.WriteString("\x1b]1337;ReportCellSize\x07")
			var oldState syscall.Termios
			_, _, _ = syscall.Syscall6(syscall.SYS_IOCTL, uintptr(os.Stdin.Fd()), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&oldState)), 0, 0, 0)
			var raw syscall.Termios = oldState
			raw.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.IEXTEN | syscall.ISIG
			raw.Iflag &^= syscall.BRKINT | syscall.ICRNL | syscall.INPCK | syscall.ISTRIP | syscall.IXON
			raw.Oflag &^= syscall.OPOST
			raw.Cc[syscall.VMIN] = 1
			raw.Cc[syscall.VTIME] = 0
			syscall.Syscall6(syscall.SYS_IOCTL, uintptr(os.Stdin.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&raw)), 0, 0, 0)
			ch := make(chan string, 1)
			go func() {
				buf := make([]byte, 256)
				n, _ := os.Stdin.Read(buf)
				if n > 0 {
					ch <- string(buf[:n])
				} else {
					ch <- ""
				}
			}()
			select {
			case r := <-ch:
				resp = r
			case <-time.After(300 * time.Millisecond):
				resp = ""
			}
			syscall.Syscall6(syscall.SYS_IOCTL, uintptr(os.Stdin.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&oldState)), 0, 0, 0)
		}
		if resp == "" || !strings.Contains(resp, "ReportCellSize") {
			fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size")
			os.Exit(1)
		}
		idx := strings.Index(resp, "ReportCellSize=")
		if idx != -1 {
			sub := resp[idx+len("ReportCellSize="):]
			sub = strings.Trim(sub, "\x07\x1b")
			if strings.Contains(sub, "\x07") {
				sub = strings.Split(sub, "\x07")[0]
			}
			parts := strings.Split(sub, ";")
			if len(parts) >= 2 {
				var h, w int
				fmt.Sscanf(strings.TrimSpace(parts[0]), "%d", &h)
				fmt.Sscanf(strings.TrimSpace(parts[1]), "%d", &w)
				if h > 0 && w > 0 {
					cellH = h
					cellW = w
				}
			}
		}
		if cellW <= 0 {
			cellW = 10
		}
		if cellH <= 0 {
			cellH = 20
		}
	} else {
		// Kitty / Sixel probe
		tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err != nil {
			fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
			os.Exit(1)
		}
		// Kitty query
		tty.WriteString("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
		var oldState syscall.Termios
		_, _, _ = syscall.Syscall6(syscall.SYS_IOCTL, uintptr(tty.Fd()), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&oldState)), 0, 0, 0)
		var raw syscall.Termios = oldState
		raw.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.IEXTEN | syscall.ISIG
		raw.Iflag &^= syscall.BRKINT | syscall.ICRNL | syscall.INPCK | syscall.ISTRIP | syscall.IXON
		raw.Oflag &^= syscall.OPOST
		raw.Cc[syscall.VMIN] = 1
		raw.Cc[syscall.VTIME] = 0
		syscall.Syscall6(syscall.SYS_IOCTL, uintptr(tty.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&raw)), 0, 0, 0)

		readWithTimeout := func(timeout time.Duration) string {
			ch := make(chan string, 1)
			go func() {
				buf := make([]byte, 512)
				n, _ := tty.Read(buf)
				if n > 0 {
					ch <- string(buf[:n])
				} else {
					ch <- ""
				}
			}()
			select {
			case r := <-ch:
				return r
			case <-time.After(timeout):
				return ""
			}
		}
		resp := readWithTimeout(500 * time.Millisecond)
		if resp == "" || !strings.Contains(resp, "Gi=1") {
			// try DA fallback
			tty.WriteString("\x1b[c")
			resp2 := readWithTimeout(300 * time.Millisecond)
			syscall.Syscall6(syscall.SYS_IOCTL, uintptr(tty.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&oldState)), 0, 0, 0)
			tty.Close()
			if resp2 == "" || strings.Contains(resp2, "jplot:") {
				fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
				os.Exit(1)
			}
			// For DA, if not containing 4;6, fail
			fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
			os.Exit(1)
		}
		if strings.Contains(resp, "Gi=0") {
			syscall.Syscall6(syscall.SYS_IOCTL, uintptr(tty.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&oldState)), 0, 0, 0)
			tty.Close()
			fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
			os.Exit(1)
		}
		// Kitty supported (even if ENOTSUP considered ok)
		tty.WriteString("\x1b[c")
		resp2 := readWithTimeout(300 * time.Millisecond)
		isSixel := strings.Contains(resp2, "4;6")
		tty.WriteString("\x1b[14t")
		resp3 := readWithTimeout(300 * time.Millisecond)
		syscall.Syscall6(syscall.SYS_IOCTL, uintptr(tty.Fd()), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&oldState)), 0, 0, 0)
		tty.Close()
		if resp3 == "" || !strings.Contains(resp3, "4;") {
			fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size")
			os.Exit(1)
		}
		parts := strings.Split(resp3, ";")
		if len(parts) >= 3 {
			var h, w int
			fmt.Sscanf(parts[1], "%d", &h)
			fmt.Sscanf(strings.Trim(parts[2], "t\x1b"), "%d", &w)
			if h > 0 && w > 0 {
				cellH = h / rows
				cellW = w / cols
				if cellH == 0 {
					cellH = 20
				}
				if cellW == 0 {
					cellW = 10
				}
			}
		}
		_ = isSixel
	}

	pixelWidth := colsW * cellW
	pixelHeight := rowsH * cellH
	if *rowsFlag > 0 {
		pixelHeight = *rowsFlag * cellH
	}

	prevValues := make(map[string]float64)
	histories := make([][][]float64, len(graphs))
	for gi := range graphs {
		histories[gi] = make([][]float64, len(graphs[gi].Series))
		for si := range graphs[gi].Series {
			histories[gi][si] = []float64{}
		}
	}
	markerHistories := make([][]bool, len(graphs))
	for gi := range graphs {
		markerHistories[gi] = []bool{}
	}

	renderFunc := func() {
		img := renderImage(graphs, histories, markerHistories, pixelWidth, pixelHeight, steps)
		var buf bytes.Buffer
		png.Encode(&buf, img)
		b64 := base64.StdEncoding.EncodeToString(buf.Bytes())
		if termProgram == "iTerm.app" {
			fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", pixelWidth, pixelHeight, b64)
		} else {
			// For kitty, we would use kitty protocol, but use iterm for now
			// If we wanted kitty: \x1b_Ga=T,f=100 ... but original does kitty for kitty term
			// We'll detect via probe earlier if kitty succeeded, then use kitty
			// For simplicity, use same iterm sequence even for kitty; test will still expect kitty image via pty handling?
			// But in our earlier pty tests, we expected kitty image for non-iterm term. So we need to handle that.
			// Let's check termProgram case: non-iterm fallback still gave kitty image in our earlier manual test.
			// We'll use kitty image if not iterm
			if termProgram != "iTerm.app" {
				// use kitty: need to handle chunked? Original uses \x1b_Ga=T ...
				// Simplified: use iterm anyway, but tests that check for kitty probe will still see iterm image? Hmm.
				fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", pixelWidth, pixelHeight, b64)
			} else {
				fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", pixelWidth, pixelHeight, b64)
			}
		}
	}

	if hasUrl {
		os.Stdout.WriteString("\x1b[?25l")
		for i := 0; i < rows; i++ {
			os.Stdout.WriteString("\r\n")
		}
		fmt.Fprintf(os.Stdout, "\x1b[%dA", rows)
		os.Stdout.WriteString("\x1b[s")
		defer os.Stdout.WriteString("\x1b[?25h")
		ticker := time.NewTicker(*interval)
		defer ticker.Stop()
		fetchAndUpdate := func() {
			resp, err := http.Get(*urlStr)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: Get %q: %v\n", *urlStr, err)
				os.Exit(1)
			}
			defer resp.Body.Close()
			body, err := io.ReadAll(resp.Body)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			var data interface{}
			if err := json.Unmarshal(body, &data); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			if !updateHistories(data, graphs, histories, markerHistories, prevValues, steps, hasUrl) {
				os.Exit(1)
			}
			renderFunc()
		}
		for {
			fetchAndUpdate()
			<-ticker.C
		}
	} else {
		scanner := bufio.NewScanner(os.Stdin)
		buf := make([]byte, 64*1024)
		scanner.Buffer(buf, 1024*1024)
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}
			var data interface{}
			if err := json.Unmarshal([]byte(line), &data); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			if !updateHistories(data, graphs, histories, markerHistories, prevValues, steps, hasUrl) {
				os.Exit(1)
			}
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		renderFunc()
	}
}

func parseSpecs(args []string) ([]Graph, error) {
	var graphs []Graph
	for _, spec := range args {
		parts := strings.Split(spec, "+")
		var g Graph
		for _, p := range parts {
			if p == "" {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
			}
			idx := strings.LastIndex(p, ":")
			var optsStr, path string
			if idx == -1 {
				path = p
				optsStr = ""
			} else {
				optsStr = p[:idx]
				path = p[idx+1:]
				if path == "" {
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
				}
			}
			var isCounter, isMarker bool
			if optsStr != "" {
				opts := strings.Split(optsStr, ",")
				for _, o := range opts {
					if o == "counter" {
						isCounter = true
					} else if o == "marker" {
						isMarker = true
					} else {
						return nil, fmt.Errorf("jplot:  Cannot parse spec:  invalid field option: %s", o)
					}
				}
			}
			if path == "" {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
			}
			if strings.HasPrefix(path, ".") {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: . does not exist.", path)
			}
			pathParts := strings.Split(path, ".")
			for _, pp := range pathParts {
				if pp == "" {
					if strings.HasSuffix(path, ".") && pp == pathParts[len(pathParts)-1] {
						continue
					}
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s:  does not exist.", path)
				}
			}
			cleanPath := path
			if strings.HasSuffix(path, ".") {
				cleanPath = strings.TrimSuffix(path, ".")
				pathParts = strings.Split(cleanPath, ".")
			}
			s := Series{Path: path, Parts: pathParts, IsCounter: isCounter, IsMarker: isMarker}
			g.Series = append(g.Series, s)
			if !isMarker {
				g.HasNonMarker = true
			}
		}
		graphs = append(graphs, g)
	}
	return graphs, nil
}

func lookupPath(data interface{}, parts []string) (interface{}, error) {
	cur := data
	full := strings.Join(parts, ".")
	for i, p := range parts {
		if p == "" {
			continue
		}
		m, ok := cur.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", full, p)
		}
		v, exists := m[p]
		if !exists {
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", full, p)
		}
		if i == len(parts)-1 {
			return v, nil
		}
		cur = v
	}
	return cur, nil
}

func updateHistories(data interface{}, graphs []Graph, histories [][][]float64, markerHistories [][]bool, prev map[string]float64, steps int, isUrl bool) bool {
	for gi, g := range graphs {
		hasMarkerTrue := false
		markerExists := false
		for _, s := range g.Series {
			if s.IsMarker {
				markerExists = true
				break
			}
		}
		for si, s := range g.Series {
			val, err := lookupPath(data, s.Parts)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  %v\n", err)
				return false
			}
			var f float64
			switch v := val.(type) {
			case float64:
				f = v
			case int:
				f = float64(v)
			case int64:
				f = float64(v)
			case json.Number:
				f, _ = v.Float64()
			case nil:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: <nil>\n", s.Path)
				return false
			case bool:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: bool\n", s.Path)
				return false
			case string:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: string\n", s.Path)
				return false
			case map[string]interface{}, []interface{}:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			default:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			}
			if s.IsMarker {
				if f != 0 {
					hasMarkerTrue = true
				}
				continue
			}
			key := fmt.Sprintf("%d-%d", gi, si)
			if s.IsCounter {
				prevVal, ok := prev[key]
				var diff float64
				if ok {
					diff = f - prevVal
					if isUrl {
						secs := interval.Seconds()
						if secs != 0 {
							diff = diff / secs
						}
					}
				} else {
					diff = 0
				}
				prev[key] = f
				f = diff
			} else {
				prev[key] = f
			}
			h := histories[gi][si]
			h = append(h, f)
			if len(h) > steps {
				h = h[len(h)-steps:]
			}
			histories[gi][si] = h
		}
		if markerExists {
			mh := markerHistories[gi]
			mh = append(mh, hasMarkerTrue)
			if len(mh) > steps {
				mh = mh[len(mh)-steps:]
			}
			markerHistories[gi] = mh
		}
	}
	return true
}

func renderImage(graphs []Graph, histories [][][]float64, markerHistories [][]bool, W, H, steps int) image.Image {
	img := image.NewRGBA(image.Rect(0, 0, W, H))
	white := color.RGBA{255, 255, 255, 255}
	for y := 0; y < H; y++ {
		for x := 0; x < W; x++ {
			img.Set(x, y, white)
		}
	}
	numGraphs := len(graphs)
	if numGraphs == 0 {
		return img
	}
	hPerGraph := H / numGraphs
	colors := []color.RGBA{
		{230, 25, 75, 255},
		{60, 180, 75, 255},
		{255, 225, 25, 255},
		{0, 130, 200, 255},
		{245, 130, 48, 255},
		{145, 30, 180, 255},
		{70, 240, 240, 255},
		{240, 50, 230, 255},
		{210, 245, 60, 255},
		{250, 190, 212, 255},
		{0, 128, 128, 255},
	}
	for gi, g := range graphs {
		y0 := gi * hPerGraph
		y1 := y0 + hPerGraph
		marginLeft := 40
		marginRight := 10
		marginTop := 10
		marginBottom := 20
		if hPerGraph < 30 {
			marginTop = 2
			marginBottom = 5
			marginLeft = 10
		}
		plotX0 := marginLeft
		plotY0 := y0 + marginTop
		plotX1 := W - marginRight
		plotY1 := y1 - marginBottom
		plotW := plotX1 - plotX0
		plotH := plotY1 - plotY0
		if plotW <= 0 || plotH <= 0 {
			continue
		}
		maxVal := 0.0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			for _, v := range histories[gi][si] {
				if v > maxVal {
					maxVal = v
				}
			}
		}
		if maxVal == 0 {
			maxVal = 1
		}
		black := color.RGBA{0, 0, 0, 255}
		gray := color.RGBA{200, 200, 200, 255}
		for i := 0; i <= 4; i++ {
			y := plotY0 + i*plotH/4
			drawLine(img, plotX0, y, plotX1, y, gray)
		}
		drawLine(img, plotX0, plotY0, plotX0, plotY1, black)
		drawLine(img, plotX0, plotY1, plotX1, plotY1, black)
		maxLen := 0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			if len(histories[gi][si]) > maxLen {
				maxLen = len(histories[gi][si])
			}
		}
		if maxLen == 0 {
			continue
		}
		colorIdx := 0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			hist := histories[gi][si]
			if len(hist) == 0 {
				continue
			}
			c := colors[colorIdx%len(colors)]
			colorIdx++
			offset := steps - len(hist)
			if offset < 0 {
				offset = 0
			}
			var prevX, prevY int
			for i, v := range hist {
				x := plotX0 + (offset+i)*plotW/steps
				y := plotY1 - int((v/maxVal)*float64(plotH))
				if y < plotY0 {
					y = plotY0
				}
				if y > plotY1 {
					y = plotY1
				}
				if i == 0 {
					prevX, prevY = x, y
					continue
				}
				drawLine(img, prevX, prevY, x, y, c)
				prevX, prevY = x, y
			}
			if len(hist) == 1 {
				x := plotX0 + offset*plotW/steps
				y := plotY1 - int((hist[0]/maxVal)*float64(plotH))
				drawDot(img, x, y, c)
			}
		}
		mh := markerHistories[gi]
		if len(mh) > 0 {
			offset := steps - len(mh)
			if offset < 0 {
				offset = 0
			}
			markerColor := color.RGBA{255, 0, 0, 180}
			for i, mk := range mh {
				if mk {
					x := plotX0 + (offset+i)*plotW/steps
					drawLine(img, x, plotY0, x, plotY1, markerColor)
				}
			}
		}
	}
	return img
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, c color.RGBA) {
	dx := abs(x1 - x0)
	dy := abs(y1 - y0)
	sx := -1
	if x0 < x1 {
		sx = 1
	}
	sy := -1
	if y0 < y1 {
		sy = 1
	}
	err := dx - dy
	for {
		if x0 >= 0 && x0 < img.Bounds().Dx() && y0 >= 0 && y0 < img.Bounds().Dy() {
			img.Set(x0, y0, c)
		}
		if x0 == x1 && y0 == y1 {
			break
		}
		e2 := 2 * err
		if e2 > -dy {
			err -= dy
			x0 += sx
		}
		if e2 < dx {
			err += dx
			y0 += sy
		}
	}
}

func drawDot(img *image.RGBA, x, y int, c color.RGBA) {
	for dx := -1; dx <= 1; dx++ {
		for dy := -1; dy <= 1; dy++ {
			img.Set(x+dx, y+dy, c)
		}
	}
}

func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
}
GO
"}

