		fmt.Fprintf(os.Stdout, "\x1b[%dA", rows)
		os.Stdout.WriteString("\x1b[s")
		defer os.Stdout.WriteString("\x1b[?25h")
		ticker := time.NewTicker(*interval)
		defer ticker.Stop()
		fetchAndUpdate := func() {
			resp, err := http.Get(*urlStr)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: Get %q: %v\n", *urlStr, err)
				os.Exit(1)
			}
			defer resp.Body.Close()
			body, err := io.ReadAll(resp.Body)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			var data interface{}
			if err := json.Unmarshal(body, &data); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			if !updateHistories(data, graphs, histories, markerHistories, prevValues, steps, hasUrl) {
				os.Exit(1)
			}
			renderFunc()
		}
		for {
			fetchAndUpdate()
			<-ticker.C
		}
	} else {
		scanner := bufio.NewScanner(os.Stdin)
		buf := make([]byte, 64*1024)
		scanner.Buffer(buf, 1024*1024)
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}
			var data interface{}
			if err := json.Unmarshal([]byte(line), &data); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			if !updateHistories(data, graphs, histories, markerHistories, prevValues, steps, hasUrl) {
				os.Exit(1)
			}
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		renderFunc()
	}
}

func parseSpecs(args []string) ([]Graph, error) {
	var graphs []Graph
	for _, spec := range args {
		parts := strings.Split(spec, "+")
		var g Graph
		for _, p := range parts {
			if p == "" {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
			}
			idx := strings.LastIndex(p, ":")
			var optsStr, path string
			if idx == -1 {
				path = p
				optsStr = ""
			} else {
				optsStr = p[:idx]
				path = p[idx+1:]
				if path == "" {
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
				}
			}
			var isCounter, isMarker bool
			if optsStr != "" {
				opts := strings.Split(optsStr, ",")
				for _, o := range opts {
					if o == "counter" {
						isCounter = true
					} else if o == "marker" {
						isMarker = true
					} else {
						return nil, fmt.Errorf("jplot:  Cannot parse spec:  invalid field option: %s", o)
					}
				}
			}
			if path == "" {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.")
			}
			if strings.HasPrefix(path, ".") {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: . does not exist.", path)
			}
			pathParts := strings.Split(path, ".")
			for _, pp := range pathParts {
				if pp == "" {
					if strings.HasSuffix(path, ".") && pp == pathParts[len(pathParts)-1] {
						continue
					}
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s:  does not exist.", path)
				}
			}
			cleanPath := path
			if strings.HasSuffix(path, ".") {
				cleanPath = strings.TrimSuffix(path, ".")
				pathParts = strings.Split(cleanPath, ".")
			}
			s := Series{Path: path, Parts: pathParts, IsCounter: isCounter, IsMarker: isMarker}
			g.Series = append(g.Series, s)
			if !isMarker {
				g.HasNonMarker = true
			}
		}
		graphs = append(graphs, g)
	}
	return graphs, nil
}

func lookupPath(data interface{}, parts []string) (interface{}, error) {
	cur := data
	full := strings.Join(parts, ".")
	for i, p := range parts {
		if p == "" {
			continue
		}
		m, ok := cur.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", full, p)
		}
		v, exists := m[p]
		if !exists {
			return nil, fmt.Errorf("cannot get %s: %s does not exist.", full, p)
		}
		if i == len(parts)-1 {
			return v, nil
		}
		cur = v
	}
	return cur, nil
}

func updateHistories(data interface{}, graphs []Graph, histories [][][]float64, markerHistories [][]bool, prev map[string]float64, steps int, isUrl bool) bool {
	for gi, g := range graphs {
		hasMarkerTrue := false
		markerExists := false
		for _, s := range g.Series {
			if s.IsMarker {
				markerExists = true
				break
			}
		}
		for si, s := range g.Series {
			val, err := lookupPath(data, s.Parts)
			if err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  %v\n", err)
				return false
			}
			var f float64
			switch v := val.(type) {
			case float64:
				f = v
			case int:
				f = float64(v)
			case int64:
				f = float64(v)
			case json.Number:
				f, _ = v.Float64()
			case nil:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: <nil>\n", s.Path)
				return false
			case bool:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: bool\n", s.Path)
				return false
			case string:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: string\n", s.Path)
				return false
			case map[string]interface{}, []interface{}:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			default:
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  invalid type %s: %T\n", s.Path, v)
				return false
			}
			if s.IsMarker {
				if f != 0 {
					hasMarkerTrue = true
				}
				continue
			}
			key := fmt.Sprintf("%d-%d", gi, si)
			if s.IsCounter {
				prevVal, ok := prev[key]
				var diff float64
				if ok {
					diff = f - prevVal
					if isUrl {
						secs := interval.Seconds()
						if secs != 0 {
							diff = diff / secs
						}
					}
				} else {
					diff = 0
				}
				prev[key] = f
				f = diff
			} else {
				prev[key] = f
			}
			h := histories[gi][si]
			h = append(h, f)
			if len(h) > steps {
				h = h[len(h)-steps:]
			}
			histories[gi][si] = h
		}
		if markerExists {
			mh := markerHistories[gi]
			mh = append(mh, hasMarkerTrue)
			if len(mh) > steps {
				mh = mh[len(mh)-steps:]
			}
			markerHistories[gi] = mh
		}
	}
	return true
}

func renderImage(graphs []Graph, histories [][][]float64, markerHistories [][]bool, W, H, steps int) image.Image {
	img := image.NewRGBA(image.Rect(0, 0, W, H))
	white := color.RGBA{255, 255, 255, 255}
	for y := 0; y < H; y++ {
		for x := 0; x < W; x++ {
			img.Set(x, y, white)
		}
	}
	numGraphs := len(graphs)
	if numGraphs == 0 {
		return img
	}
	hPerGraph := H / numGraphs
	colors := []color.RGBA{
		{230, 25, 75, 255},
		{60, 180, 75, 255},
		{255, 225, 25, 255},
		{0, 130, 200, 255},
		{245, 130, 48, 255},
		{145, 30, 180, 255},
		{70, 240, 240, 255},
		{240, 50, 230, 255},
		{210, 245, 60, 255},
		{250, 190, 212, 255},
		{0, 128, 128, 255},
	}
	for gi, g := range graphs {
		y0 := gi * hPerGraph
		y1 := y0 + hPerGraph
		marginLeft := 40
		marginRight := 10
		marginTop := 10
		marginBottom := 20
		if hPerGraph < 30 {
			marginTop = 2
			marginBottom = 5
			marginLeft = 10
		}
		plotX0 := marginLeft
		plotY0 := y0 + marginTop
		plotX1 := W - marginRight
		plotY1 := y1 - marginBottom
		plotW := plotX1 - plotX0
		plotH := plotY1 - plotY0
		if plotW <= 0 || plotH <= 0 {
			continue
		}
		maxVal := 0.0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			for _, v := range histories[gi][si] {
				if v > maxVal {
					maxVal = v
				}
			}
		}
		if maxVal == 0 {
			maxVal = 1
		}
		black := color.RGBA{0, 0, 0, 255}
		gray := color.RGBA{200, 200, 200, 255}
		for i := 0; i <= 4; i++ {
			y := plotY0 + i*plotH/4
			drawLine(img, plotX0, y, plotX1, y, gray)
		}
		drawLine(img, plotX0, plotY0, plotX0, plotY1, black)
		drawLine(img, plotX0, plotY1, plotX1, plotY1, black)
		maxLen := 0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			if len(histories[gi][si]) > maxLen {
				maxLen = len(histories[gi][si])
			}
		}
		if maxLen == 0 {
			continue
		}
		colorIdx := 0
		for si, s := range g.Series {
			if s.IsMarker {
				continue
			}
			hist := histories[gi][si]
			if len(hist) == 0 {
				continue
			}
			c := colors[colorIdx%len(colors)]
			colorIdx++
			offset := steps - len(hist)
			if offset < 0 {
				offset = 0
			}
			var prevX, prevY int
			for i, v := range hist {
				x := plotX0 + (offset+i)*plotW/steps
				y := plotY1 - int((v/maxVal)*float64(plotH))
				if y < plotY0 {
					y = plotY0
				}
				if y > plotY1 {
					y = plotY1
				}
				if i == 0 {
					prevX, prevY = x, y
					continue
				}
				drawLine(img, prevX, prevY, x, y, c)
				prevX, prevY = x, y
			}
			if len(hist) == 1 {
				x := plotX0 + offset*plotW/steps
				y := plotY1 - int((hist[0]/maxVal)*float64(plotH))
				drawDot(img, x, y, c)
			}
		}
		mh := markerHistories[gi]
		if len(mh) > 0 {
			offset := steps - len(mh)
			if offset < 0 {
				offset = 0
			}
			markerColor := color.RGBA{255, 0, 0, 180}
			for i, mk := range mh {
				if mk {
					x := plotX0 + (offset+i)*plotW/steps
					drawLine(img, x, plotY0, x, plotY1, markerColor)
				}
			}
		}
	}
	return img
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, c color.RGBA) {
	dx := abs(x1 - x0)
	dy := abs(y1 - y0)
	sx := -1
	if x0 < x1 {
		sx = 1
	}
	sy := -1
	if y0 < y1 {
		sy = 1
	}
	err := dx - dy
	for {
		if x0 >= 0 && x0 < img.Bounds().Dx() && y0 >= 0 && y0 < img.Bounds().Dy() {
			img.Set(x0, y0, c)
		}
		if x0 == x1 && y0 == y1 {
			break
		}
		e2 := 2 * err
		if e2 > -dy {
			err -= dy
			x0 += sx
		}
		if e2 < dx {
			err += dx
			y0 += sy
		}
	}
}

func drawDot(img *image.RGBA, x, y int, c color.RGBA) {
	for dx := -1; dx <= 1; dx++ {
		for dy := -1; dy <= 1; dy++ {
			img.Set(x+dx, y+dy, c)
		}
	}
}

func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
}
GO
"}

