	stepsFlag = flag.Int("steps", 100, "Number of values to plot. (default 100)")
	urlStr = flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")
)

type Series struct {
	Path      string
	Parts     []string
	IsCounter bool
	IsMarker  bool
}

type Graph struct {
	Series       []Series
	HasNonMarker bool
}

func isTerminal(fd int) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return err == 0
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getWinsize(fd int) (int, int, error) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, errno
	}
	return int(ws.Col), int(ws.Row), nil
}

func setRaw(fd int) (*syscall.Termios, error) {
	var old syscall.Termios
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&old)), 0, 0, 0)
	if errno != 0 {
		return nil, errno
	}
	var raw syscall.Termios = old
	raw.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.IEXTEN | syscall.ISIG
	raw.Iflag &^= syscall.BRKINT | syscall.ICRNL | syscall.INPCK | syscall.ISTRIP | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	_, _, errno = syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&raw)), 0, 0, 0)
	if errno != 0 {
		return nil, errno
	}
	return &old, nil
}

func restore(fd int, old *syscall.Termios) {
	syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(old)), 0, 0, 0)
}

func readTtyWithTimeout(fd int, timeout time.Duration) string {
	ch := make(chan string, 1)
	go func() {
		buf := make([]byte, 512)
		n, _ := syscall.Read(fd, buf)
		if n > 0 {
			ch <- string(buf[:n])
		} else {
			// try os.NewFile
			f := os.NewFile(uintptr(fd), "")
			if f != nil {
				n2, _ := f.Read(buf)
				if n2 > 0 {
					ch <- string(buf[:n2])
					return
				}
			}
			ch <- ""
		}
	}()
	select {
	case r := <-ch:
		return r
	case <-time.After(timeout):
		return ""
	}
}

func getTtyFd() int {
	// Prefer stdout if terminal
	if isTerminal(int(os.Stdout.Fd())) {
		return int(os.Stdout.Fd())
	}
	if isTerminal(int(os.Stdin.Fd())) {
		return int(os.Stdin.Fd())
	}
	// try /dev/tty
	f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err == nil {
		fd := int(f.Fd())
		// we need to keep file open? For now return fd and leak
		return fd
	}
	return -1
}

func main() {
	isStdoutTerm := isTerminal(int(os.Stdout.Fd()))
	termProgram := os.Getenv("TERM_PROGRAM")

	if !isStdoutTerm && termProgram != "iTerm.app" {
		os.Stdout.WriteString("\x1b[c")
	}

	flag.Usage = func() {
		fmt.Fprint(os.Stderr, usageStr)
	}

	for _, a := range os.Args[1:] {
		if a == "-h" || a == "--help" || a == "-help" || a == "--h" {
			fmt.Fprint(os.Stderr, usageStr)
			os.Exit(0)
		}
		if a == "-h=true" || a == "--help=true" || a == "-help=true" {
			fmt.Fprint(os.Stderr, usageStr)
			os.Exit(0)
		}
	}

	flag.Parse()

	if os.Getenv("TERM") == "screen" && termProgram == "iTerm.app" {
		fmt.Fprintln(os.Stdout, "jplot:  screen and tmux not supported")
		os.Exit(1)
	}

	if !isStdoutTerm {
		if termProgram != "iTerm.app" {
			fmt.Fprintln(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required")
			os.Exit(1)
		}
	}

	if flag.NArg() == 0 {
		fmt.Fprint(os.Stderr, usageStr)
		os.Exit(1)
	}

	if !isStdoutTerm {
		fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device")
		os.Exit(1)
	}
	cols, rows, err := getWinsize(int(os.Stdout.Fd()))
	if err != nil || cols == 0 || rows == 0 {
		fmt.Fprintln(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device")
		os.Exit(1)
	}

	steps := *stepsFlag
	if steps == 0 {
		fmt.Fprintln(os.Stderr, "panic: runtime error: index out of range [-1]")
		fmt.Fprintln(os.Stderr, "")
		fmt.Fprintln(os.Stderr, "goroutine 18 [running]:")
		fmt.Fprintln(os.Stderr, "github.com/rs/jplot/graph.New({{_, _, _}}, _, _, _)")
		fmt.Fprintln(os.Stderr, "\tgithub.com/rs/jplot/graph/graph.go:?? +0x??")
		os.Exit(2)
	}
	if steps < 0 {
		fmt.Fprintln(os.Stderr, "panic: runtime error: makeslice: len out of range")
		fmt.Fprintln(os.Stderr, "")
		fmt.Fprintln(os.Stderr, "goroutine 6 [running]:")
		fmt.Fprintln(os.Stderr, "github.com/rs/jplot/data.(*Points).getLocked(...)")
		fmt.Fprintln(os.Stderr, "\tgithub.com/rs/jplot/data/points.go:?? +0x??")
		os.Exit(2)
