import subprocess, pty, os, fcntl, termios, struct, select, time
def run_pty(cmd_args, input_lines):
    master, slave = pty.openpty()
    winsize = struct.pack("HHHH", 24, 80, 0, 0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    env=os.environ.copy()
    env["TERM"]="xterm-256color"
    env["TERM_PROGRAM"]="iTerm.app"
    cmd = "./executable " + " ".join(cmd_args)
    proc=subprocess.Popen(cmd, shell=True, stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=env)
    for line in input_lines:
        proc.stdin.write((line+"\n").encode())
    proc.stdin.close()
    os.set_blocking(master, False)
    data=b""
    start=time.time()
    responded=False
    while time.time()-start < 5:
        r,_,_=select.select([master],[],[],0.3)
        if not r:
            if proc.poll() is not None:
                break
            continue
        chunk=os.read(master,8192)
        if not chunk:
            break
        data+=chunk
        if not responded and b"ReportCellSize" in chunk and b"File" not in chunk:
            time.sleep(0.05)
            os.write(master, b"\x1b]1337;ReportCellSize=20;10\x07")
            responded=True
            continue
        if b"File" in chunk or b"jplot:" in chunk:
            if b"File" in chunk:
                time.sleep(0.4)
                while True:
                    r,_,_=select.select([master],[],[],0.2)
                    if not r: break
                    c=os.read(master,8192)
                    if not c: break
                    data+=c
            break
    proc.terminate()
    os.close(master); os.close(slave)
    return data
for path, js in [("'a.'",'{"a":1}'), ("'a.'",'{"a":{"":1}}')]:
    d=run_pty([path],[js])
    print(path, js, "->", "File" in d, d[:200] if d else b"")
